export function ownerF144Reconstruction(components:BuildingComponent[]):{components:BuildingComponent[];stats:OwnerReconstructionStats}{const stats:OwnerReconstructionStats={objects:0,vertices:0,triangles:0,originalVertices:0,sourceRetained:true,actualVisualAccepted:false,components:[]};if(!components.some(c=>c.city==='frankfurt'&&ownerF144Identity(c)))return{components,stats};const duplicates=F144_IDS.some(i=>components.filter(c=>c.city===i.city&&c.objectId===i.objectId&&c.partId===i.partId).length>1);if(duplicates){stats.error='F144 duplicate native carrier';return{components,stats};}return{components:components.map(c=>{if(c.city!=='frankfurt'||!ownerF144Identity(c))return c;if(!immutable(c)){stats.error='F144 unchanged native carrier required';return c;}const batches=DISPLAY[c.partId].map(b=>({...b,positions:[...b.positions],normals:[...b.normals],indices:[...b.indices],color:[...b.color],frames:[...b.frames],paint:[...b.paint],writeMask:[...b.writeMask]}));const vertices=batches.reduce((s,b)=>s+b.positions.length/3,0),triangles=batches.reduce((s,b)=>s+b.indices.length/3,0);if(vertices)stats.objects++;stats.vertices+=vertices;stats.triangles+=triangles;stats.originalVertices+=c.batches.reduce((s,b)=>s+b.positions.length/3,0);stats.components.push({objectId:c.objectId,partId:c.partId,sourcePartId:c.partId,patchSHA256:F144_RECONSTRUCTION_SHA,vertices,triangles,geometryRole:'owner-authorized-reconstruction'});return{...c,batches,displayEstimates:{...c.displayEstimates,F144Exterior:{sourceRetained:true,sourceOnlyAlias:batches.length===0,patchSHA:F144_RECONSTRUCTION_SHA,originalNativeGettersUnchanged:true,photoAndSourceDerivedDisplay:true,notFormalBuildingGroup:true,allVerticalDatumsExplicitDisplayEstimates:true,availableViewportSubsetReconstructedIndependently:true,wholeSourceEvidenceExpected10:true}}};}),stats};}
export function ownerF144BaseMaterials(components:BuildingComponent[],paint:Float32Array,frames:Float32Array){let offset=0,objects=0,vertices=0;for(const c of components){const match=c.city==='frankfurt'&&ownerF144Identity(c)&&!!c.displayEstimates?.F144Exterior;if(match)objects++;for(const b of c.batches){const count=b.positions.length/3;if(match){const a=b as Batch;for(let j=0;j<count;j++)if(a.writeMask[j]){paint.set(a.paint.slice(j*4,j*4+4),4*(offset+j));frames.set(a.frames.slice(j*5,j*5+5),5*(offset+j));vertices++;}}offset+=count;}}return{objects,vertices,actualVisualAccepted:false};}
